// Imports
import BulkApprovalDialog from "@/components/Approvals/BulkAprrovalDialog.vue";
import { API, graphqlOperation } from "aws-amplify";
import { EventBus } from "@/main";
import { formatedatetime } from "@/JsonFiles/DateFormate.js";
import { list_pending_workflows_v1, get_particular_workflow_details } from "@/graphql/queries.js";
import { get_workflow_payload } from "@/mixins/GetWorkflowDetails.js";
import { get_workflows } from "@/mixins/GetWorkflowsummary.js";

// Components
import SnackBar from "@/components/SnackBar.vue";
import OverlayComp from "@/components/OverlayComp.vue";
import FormInfo from "@/components/FormFields/FormInfo.vue";
import ApprovalEdit from "@/components/FormFields/ApprovalEdit.vue";
import DirectoryApprovals from "@/components/LookitUPDirectiory/AllDialogs/DirectoryApprovals.vue";
import BulkForwardWorkflows from "@/components/Approvals/BulkForwardWorkflows.vue";
import BulkRejectWorkflows from "@/components/Approvals/BulkRejectWorkflows.vue";
import CreateTicketDialog from "../Tickets/CreateTicketDialog.vue";
import html2canvas from "html2canvas";
export default {
  // Components
  components: {
    SnackBar,
    FormInfo,
    ApprovalEdit,
    OverlayComp,
    DirectoryApprovals,
    BulkForwardWorkflows,
    BulkRejectWorkflows,
    CreateTicketDialog,
    BulkApprovalDialog
  },
  // Mixins
  mixins: [get_workflow_payload, get_workflows],
  // Data
  data() {
    return {
      // Boolean properties
      singleSelect: false,
      tableLoading: false,
      overlay: false,
      submittedInfo: false,
      editableField: false,
      directoryApprovalsDialog: false,
      bulkRejectDialog: false,
      bulkForwardDialog: false,
      isVisible: false,
      fixed: true,
      // String properties
      approvalType: "",
      actionItem: "",
      formAction: "Pending",
      formActionType: "initiate",
      summarylabel: "",
      searchsummary: "",
      search: "",
      filterByAction: "",
      // Number properties
      formCheck: 0,
      componentCheck: 0,
      bulkAction: 0,
      currentPage: 1,
      itemsPerPage: 20,
      totalItems: 0,
      windowHeight: 0,
      // Array properties
      selectedItemsForward: [],
      tableData: [],
      workflowItems: [],
      selectItems: [],
      allselecctedRecords: [],
      // Object properties
      SnackBarComponent: {},
      formDetails: {},
      rowInfo: {},
      pagination: {
        itemsPerPage: 20,
        page: 1
      },
      // Other properties
      onBoardDialog: false,
      formViewDailog: false,
      next_token: null,
      goLoading: false,
      //Screenshot Values
      DialogCreateTicket: false,
      ScreenshotFile: null,
      bulkapprovalDialog: false,
      orgDetails: {
        bucket_name: "stichh-medias",
        region: "us-east-1"
      },
      // Table headers
      headers: [{
        title: "Transaction Id",
        key: "transaction_id",
        sortable: false
      }, {
        title: "Workflow Name",
        key: "workflow_name",
        sortable: false
      }, {
        title: "Summary Fields",
        key: "summary_field_1",
        sortable: false
      }, {
        title: "Initiated By",
        key: "workflow_initiated_name",
        sortable: false
      }, {
        title: "Initiated On",
        key: "workflow_initiated_on",
        sortable: false
      }]
    };
  },
  // Computed properties
  computed: {
    modernHeaders() {
      return [{
        title: "Transaction Id",
        key: "transaction_id",
        sortable: false
      }, {
        title: "Workflow Name",
        key: "workflow_name",
        sortable: false
      }, {
        title: "Summary Fields",
        key: "summary_field_1",
        sortable: false
      }, {
        title: "Initiated By",
        key: "workflow_initiated_name",
        sortable: false
      }, {
        title: "Initiated On",
        key: "workflow_initiated_on",
        sortable: false
      }];
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.tableData.slice(start, end);
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const pages = [];
      const start = Math.max(1, this.currentPage - 2);
      const end = Math.min(this.pageCount, this.currentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  // Watchers
  watch: {
    // When page changes, load more if needed
    currentPage(newVal, oldVal) {
      if (newVal > oldVal && this.next_token) {
        this.get_pending_workflows();
      } else {
        const table = document.querySelector(".modern-data-table");
        if (table) table.scrollIntoView({
          behavior: "smooth",
          block: "start"
        });
      }
    }
  },
  // Lifecycle hooks
  async created() {
    this.isVisible = true;
    this.windowHeight = window.innerHeight - 220;
    await Promise.all([this.get_pending_workflows(), this.get_workflows()]);
    this.fetch_all_workflows();
  },
  // Methods
  methods: {
    refresh_list() {
      this.next_token = null;
      this.get_pending_workflows();
    },
    async TakeScreenshot() {
      const target = document.body;
      const canvas = await html2canvas(target, {
        scale: window.devicePixelRatio || 2,
        useCORS: true,
        logging: false,
        windowWidth: document.documentElement.scrollWidth,
        windowHeight: document.documentElement.scrollHeight
      });
      const dataUrl = canvas.toDataURL("image/png");
      const blob = await (await fetch(dataUrl)).blob();
      const file = new File([blob], "screenshot.png", {
        type: "image/png"
      });
      this.ScreenshotFile = file;
      this.DialogCreateTicket = true;
    },
    DialogCreateTicketEmit() {
      this.DialogCreateTicket = false;
    },
    getFileName(url) {
      if (typeof url === "string") {
        const match = url.match(/[^\/]+\.(jpg|png|xlsx|jpeg|gif|bmp|tiff|pdf|doc|docx|xls|csv|txt|mp4|mp3|avi|mkv)$/i);
        return match ? match[0] : url;
      } else {
        return url;
      }
    },
    // Navigation methods
    back_call() {
      this.$router.push("/home/DashboardView");
    },
    // Utility methods
    formatDate(timestamp, format) {
      const date = new Date(timestamp * 1000);
      const day = String(date.getDate()).padStart(2, "0");
      const numericMonth = String(date.getMonth() + 1).padStart(2, "0");
      const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
      const monthName = monthNames[date.getMonth()];
      const year = date.getFullYear();
      const formatMap = {
        DD: day,
        MM: numericMonth,
        YYYY: year,
        Month: monthName
      };
      return format.replace(/DD|MM|YYYY|Month/gi, matched => formatMap[matched]);
    },
    getFileName(url) {
      if (typeof url === "string") {
        const match = url.match(/[^\/]+\.(jpg|png|xlsx|jpeg|gif|bmp|tiff|pdf|doc|docx|xls|csv|txt|mp4|mp3|avi|mkv)$/i);
        return match ? match[0] : url;
      } else {
        return url;
      }
    },
    fetch_value(date) {
      return formatedatetime(date);
    },
    fetch_name(formType, formInfo) {
      var data = "";
      if (formType == "MEMBER_ONBOARD") {
        data = formInfo.workflow_payload.first_name;
      } else {
        data = formInfo.workflow_payload.user_id_text;
      }
      return data;
    },
    // Workflow management methods
    fetch_all_workflows() {
      this.workflowItems = [];
      this.summaryOrgWorkflows.forEach(element => {
        this.workflowItems.push(element.workflow_name);
      });
      this.workflowItems.sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()));
    },
    // Bulk action methods
    bulk_reject() {
      var valid = true;
      this.allselecctedRecords = [];
      if (this.selectedItemsForward.length > 20) {
        valid = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "The maximum number of records that can be reject at one time is 20",
          timeout: 5000,
          Top: true
        };
      }
      if (valid) {
        this.componentCheck = 5;
        this.bulkRejectDialog = true;
        this.allselecctedRecords = this.selectedItemsForward;
      }
    },
    bulk_forward() {
      var valid = true;
      this.allselecctedRecords = [];
      if (this.selectedItemsForward.length > 20) {
        valid = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "The maximum number of records that can be forwarded at one time is 20",
          timeout: 5000,
          Top: true
        };
      }
      if (valid) {
        this.componentCheck = 4;
        this.bulkForwardDialog = true;
        this.allselecctedRecords = this.selectedItemsForward;
      }
    },
    // Pagination methods
    get_submitworkflow_Pagination() {
      if (this.next_token) {
        this.get_pending_workflows();
      }
    },
    // Filter methods
    input_check() {
      if (this.filterByAction != "") {
        this.summarylabel = "";
        this.searchsummary = "";
      }
    },
    bulk_aprroval() {
      let valid = true;
      this.allselecctedRecords = [];
      if (this.selectedItemsForward.length === 0) {
        valid = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Please select at least one workflow",
          timeout: 5000,
          Top: true
        };
      }
      if (this.selectedItemsForward.length > 20) {
        valid = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "The maximum number of records that can be approved at one time is 20",
          timeout: 5000,
          Top: true
        };
      }
      if (valid) {
        this.componentCheck = 6;
        this.bulkapprovalDialog = true;
        this.allselecctedRecords = this.selectedItemsForward;
      }
    },
    filter_data() {
      if (this.summarylabel != "" && this.searchsummary == "") {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Search by summary with a minimum of three characters",
          timeout: 5000,
          Top: true
        };
      } else {
        this.tableData = [];
        this.goLoading = true;
        this.next_token = null;
        this.get_pending_workflows();
      }
    },
    clear_data() {
      this.filterByAction = "";
      this.summarylabel = "";
      this.tableData = [];
      this.next_token = null;
      this.selectItems = [];
      this.get_pending_workflows();
    },
    // API methods
    async get_pending_workflows() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_pending_workflows_v1, {
          input: {
            organization_id: data.organization.organization_id,
            user_email_id: data.user.user_email_id,
            limit: 21,
            nextToken: this.next_token,
            workflow_name: this.filterByAction != "" ? this.filterByAction : undefined,
            summary_field_1: this.summarylabel == "summary_field_1" ? this.searchsummary.trim().length == 0 ? undefined : this.searchsummary : undefined,
            summary_field_2: this.summarylabel == "summary_field_2" ? this.searchsummary.trim().length == 0 ? undefined : this.searchsummary : undefined
          }
        }));
        this.tableLoading = false;
        this.goLoading = false;
        var response = JSON.parse(result.data.list_pending_workflows_v1);
        let array = [];
        if (response.Status == "SUCCESS") {
          this.goLoading = false;
          this.next_token = response.nextToken;
          array = this.tableData.concat(response.workflow);
          this.tableData = array;
          const uniqueArrayOfObjects = this.tableData.filter((obj, index, self) => index === self.findIndex(o => o.initiate_id === obj.initiate_id));
          this.tableData = uniqueArrayOfObjects;
          this.totalItems = this.tableData.length;
        } else {
          this.goLoading = false;
        }
      } catch (error) {
        this.tableLoading = false;
        this.goLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    async get_transaction() {
      try {
        let result = await API.graphql(graphqlOperation(get_particular_workflow_details, {
          input: {
            initiate_id: this.formDetails.initiate_id
          }
        }));
        var response = JSON.parse(result.data.get_particular_workflow_details);
        if (response.Status == "SUCCESS") {
          this.detailsform = response.data[0];
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    // Event handlers
    async handleClick(click, value) {
      this.overlay = true;
      this.rowInfo = value.item;
      localStorage.setItem("initiatedBy", value.item.workflow_initiated_name);
      this.$store.commit("SetInitiatorId", value.item.initiate_id);
      await this.get_workflow_payload();
      this.overlay = false;
      var dataCheck = this.workflowInfoPaylod.workflow_template.every(obj => obj.is_readonly === true);
      if (dataCheck == true && this.workflowInfoPaylod.form_unique_type != "DIRECTORY_EDIT_ENTRY_FORM" && this.workflowInfoPaylod.form_unique_type != "DIRECTORY_ADD_ENTRY_FORM" && this.workflowInfoPaylod.form_unique_type != "DIRECTORY_DELETE_ENTRY_FORM" && this.workflowInfoPaylod.form_unique_type != "DIRECTORY_ACCESS_FORM") {
        this.componentCheck = 1;
        this.actionItem = "Pending";
        this.submittedInfo = true;
        this.formDetails = this.workflowInfoPaylod;
      } else if (dataCheck == true && (this.workflowInfoPaylod.form_unique_type == "DIRECTORY_EDIT_ENTRY_FORM" || this.workflowInfoPaylod.form_unique_type == "DIRECTORY_ADD_ENTRY_FORM" || this.workflowInfoPaylod.form_unique_type == "DIRECTORY_DELETE_ENTRY_FORM" || this.workflowInfoPaylod.form_unique_type == "DIRECTORY_ACCESS_FORM")) {
        this.componentCheck = 3;
        this.actionItem = "Pending";
        this.submittedInfo = true;
        this.formDetails = this.workflowInfoPaylod;
        this.directoryApprovalsDialog = true;
      } else {
        this.componentCheck = 2;
        this.actionItem = "Pending";
        this.editableField = true;
        this.formDetails = this.workflowInfoPaylod;
      }
    },
    onSelectionChange(selected) {
      this.selectedItemsForward = selected;
    },
    // Notification methods
    popups(val) {
      if (val == 0) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "While rejection comments are mandatory",
          timeout: 5000,
          Top: true
        };
      }
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.bulkRejectDialog = false;
      this.submittedInfo = false;
      this.editableField = false;
      this.next_token = null;
      this.tableData = [];
      this.directoryApprovalsDialog = false;
      this.bulkForwardDialog = false;
      this.bulkapprovalDialog = false;
      this.allselecctedRecords = [];
      this.selectedItemsForward = [];
      await this.get_pending_workflows();
    }
  }
};
